#include <mutex>
#include <condition_variable>
#include <atomic>
#include <thread>
#include <queue>

class Semaphore {
 private:
  std::atomic<int> count;
  std::mutex mutex_;
  std::condition_variable cv_;
  bool initialized = false; 

 public:
  Semaphore(int initialValue) : count(initialValue) {}
  ~Semaphore() {}

  void increment() {
    std::unique_lock<std::mutex> lock(mutex_);
    ++count;
    cv_.notify_one(); 
  }

  void decrement() {
    std::unique_lock<std::mutex> lock(mutex_);
    if (count > 0) {
      --count;
    } else {
      // Handle underflow scenarios 
    }
    cv_.notify_one();
  }

  int getCount() const {
    return count.load();
  }
};
```



