async function fetchConfig(apiUrl) {
  let retries = 0;
  while (retries < 3) {
    try {
      const response = await fetch(apiUrl);
      if (!response.ok) {
        throw new Error('API request failed');
      }
      return await response.json();
    } catch (error) {
      console.warn(`API request failed, retrying...`);
      retries++;
      await sleep(2000); // Exponential backoff - wait for 2 seconds before retry
    }
  }

  throw new Error('Maximum retries exceeded');
}

async function runTest(moduleName, testName, config) {
  // ... Implementation to execute individual test using mocks and logging errors
}

class PromiseQueue {
  constructor() {
    this.queue = [];
    this.processing = false;
  }

  add(task) {
    this.queue.push(task);
    if (!this.processing) {
      this.process();
    }
  }

  async process() {
    this.processing = true;
    while (this.queue.length > 0) {
      const task = this.queue.shift();
      await task();
    }
    this.processing = false;
  }
}



function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

```

