  if (memoryPool.has(cacheKey)) {
    return memoryPool.get(cacheKey);
  }

  try {
    const response = await axios.get(`https://storage-api/file/${filePath}`, {
      params: {
        range: `${startByte}-${endByte}` 
      },
      headers: {
        // Authentication headers 
      }
    });

    const segmentData = response.data;
    memoryPool.set(cacheKey, segmentData);
    return segmentData;

  } catch (error) {
    console.error(`Error retrieving segment:`, error);
    throw new Error('Failed to retrieve media segment'); 
  }
}

