['```java
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class DynamicDeserializationService {

    private final Map<String, Class<?>> registeredClasses;
    private final ConcurrentHashMap<String, Object> deserializedInstances = new ConcurrentHashMap<>();
    private final MetadataRetriever metadataRetriever;
    private final int maxPoolSize;
    private final boolean enableLazyLoading;

    public DynamicDeserializationService(MetadataRetriever metadataRetriever, 
                                       int maxPoolSize,
                                       boolean enableLazyLoading) {
        this.metadataRetriever = metadataRetriever;
        this.maxPoolSize = maxPoolSize;
        this.enableLazyLoading = enableLazyLoading;
        registeredClasses = new HashMap<>();
    }

    public <T> T deserialize(byte[] data, String className) throws IOException {
        if (deserializedInstances.containsKey(className)) {
            return (T) deserializedInstances.get(className);
        } else {
            try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
                Class<?> clazz = registeredClasses.get(className);
                if (clazz == null) {
                    throw new ClassNotFoundException("Unknown class: " + className);
                }
                T instance = (T) ois.readObject();
                deserializedInstances.put(className, instance);
                return instance;
            } catch (ClassNotFoundException e) {
                throw new IOException("Invalid class reference", e);
            } 
        }
    }

    public void registerClass(String className, Class<?> clazz) {
        registeredClasses.put(className, clazz);
    }

    // ... Other methods for configuration, metadata retrieval, logging, etc.
}



