    for attempt in 0..10 {
        match std::fs::create_dir_all(&generated_path) {
            Ok(_) => {
                std::env::set_var("DIRECTORY_PATH", generated_path);
                log::info!("Directory created successfully: {}", generated_path);
                return Ok(generated_path);
            }
            Err(e) => {
                if let std::io::ErrorKind::AlreadyExists = e.kind() {
                    // Handle existing directory error gracefully.
                    log::warn!(
                        "Directory already exists: {} - Retrying attempt {}",
                        generated_path, attempt + 1
                    );
                    break; // Exit loop if the path already exists.
                } else {
                    log::warn!("Failed to create directory on attempt {}, retrying...", attempt + 1);
                    std::thread::sleep(Duration::from_millis(2 << attempt));
                }
            }
        }
    }

    Err(Error::DirectoryCreationFailed)
}

