class DynamicJSONifiable:
    _factory_registry = {}

    def __init__(self, data=None):
        if data:
            self._deserialize(data)

    @classmethod
    def register_factory(cls, id, factory):
        cls._factory_registry[id] = factory

    @classmethod
    def create_instance(cls, id, data=None):
        factory = cls._factory_registry.get(id)
        if factory:
