['```cpp
#include <mutex>
#include <condition_variable>
#include <queue>

class Semaphore {
 public:
  Semaphore(int initial_value) : count_(initial_value), mutex_() {}

  // Atomically increments the semaphore value
  void increment() {
    std::lock_guard<std::mutex> lock(mutex_);
    ++count_;
    cv_.notify_one();
  }

  // Atomically decrements the semaphore value
  bool decrement() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (count_ > 0) {
      --count_;
      return true;
    } else {
      return false;
    }
  }

  // Waits until the semaphore value is greater than zero
  void wait() {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return count_ > 0; });
  }

 private:
  int count_;
  std::mutex mutex_;
  std::condition_variable cv_;
};


```']

