      const response = await fetch(script.source);
      const scriptContent = await response.text();
      await cache.set(script.id, scriptContent, 60 * 60); // Cache for 1 hour
      console.log(`Fetched and cached script: ${script.id}`);
      return scriptContent; 
    } catch (error) {
      // Handle errors with exponential backoff, circuit breaker, etc.
