import org.apache.kafka.clients.producer.*;
import java.util.Properties;

public class LogProducer {

    private static final String TOPIC_NAME = "logs"; // Kafka topic for logs

    public static void main(String[] args) {
        // Configure Kafka producer properties
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092"); 
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, "org.apache.kafka.common.serialization.StringSerializer");
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, "org.apache.kafka.common.serialization.StringSerializer");

        // Create Kafka producer instance
        KafkaProducer<String, String> producer = new KafkaProducer<>(props);

        // Simulate log events from different sources
        for (int i = 0; i < 1000; i++) {
            String logMessage = "Log message: " + i;
            producer.send(new ProducerRecord<>(TOPIC_NAME, logMessage)); // Send log to Kafka topic
        }

        // Close the producer
        producer.close();
    }
}



```




