        this.refreshTokenValidationUrl = refreshTokenValidationUrl;
        this.secretKey = secretKey;
    }

    public boolean validateAccessToken(JsonNode payload) throws JwtException, IOException {
        // 1. Extract the token from the JSON payload
        String accessToken = payload.get("accessToken").asText();

        // 2. Decode and verify the access token
        Jws<Claims> jws = Jwts.parserBuilder()
                .setSigningKey(secretKey) // Your secret key
                .build()
                .parseClaimsJws(accessToken);

        // 3. Retrieve the refresh token from the claims
        String refreshToken = jws.getBody().get("refreshToken", String.class);

        // 4. Validate the refresh token against the external API
        if (!validateRefreshToken(refreshToken)) {
            return false;
        }

        return true;
    }

