from flask import Flask, request, jsonify
from cloud_storage_adapters import AWSAdapter, GCSAdapter, AzureAdapter  

app = Flask(__name__)

@app.route('/backup', methods=['POST'])
def backup_file():
    user_data = request.json
    cloud_provider = user_data['cloud_provider']
    file_path = user_data['file_path'] 

    if cloud_provider == 'aws':
        adapter = AWSAdapter()
    elif cloud_provider == 'gcs':
        adapter = GCSAdapter()
    elif cloud_provider == 'azure':
        adapter = AzureAdapter()
    else:
        return jsonify({'error': 'Invalid cloud provider'}), 400

    try:
        adapter.backup_file(file_path)
        return jsonify({'message': 'Backup successful'}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500


if __name__ == '__main__':
    app.run(debug=True)

```



