class DataProcessor {
public:
  DataProcessor() : processingThread(std::bind(&DataProcessor::processIncomingData, this)) {}

  void enqueueData(const std::string& data) {
    std::unique_lock<std::mutex> lock(dataQueueMutex);
    dataQueue.push(data);
    cv.notify_one();
  }

  void start() { processingThread.join(); }

private:
  void processIncomingData() {
    while (true) {
      std::unique_lock<std::mutex> lock(dataQueueMutex);
      cv.wait(lock, [this] { return !dataQueue.empty(); });
      const std::string& data = dataQueue.front();
      dataQueue.pop();
      lock.unlock();

