#include <mutex>
#include <condition_variable>
#include <atomic>

class Semaphore {
 public:
  explicit Semaphore(int initial_value) : count_(initial_value), mutex_() {}

  void acquire() {
    std::unique_lock<std::mutex> lock(mutex_);
    while (count_ == 0) {
      cv_.wait(lock);
    }
    --count_;
    // Log acquisition operation here
  }

  void release() {
    std::lock_guard<std::mutex> lock(mutex_);
    ++count_;
    cv_.notify_one();
    // Log release operation here
  }

 private:
  int count_;
  std::mutex mutex_;
  std::condition_variable cv_;
};


