class TransactionQueue {
public:
  void enqueue(const Transaction& transaction) {
    std::unique_lock<std::mutex> lock(m);
    queue.push(transaction);
    cv.notify_one(); 
  }

  Transaction dequeue() {
    std::unique_lock<std::mutex> lock(m);
    cv.wait(lock, [this]{ return !queue.empty(); });
    Transaction transaction = queue.front();
    queue.pop();
    return transaction;
  }

private:
  std::queue<Transaction> queue;
  std::mutex m;
  std::condition_variable cv;
};

// Transaction processor thread
void processTransactions(TransactionQueue& queue, FinancialAPI* api) {
  while (true) {
    Transaction transaction = queue.dequeue();
    if (api->processTransaction(transaction)) {
      // Successful processing
      std::cout << "Processed transaction: " << transaction.id << std::endl;
    } else {
      // Handle API failure 
      std::cerr << "Failed to process transaction: " << transaction.id << std::endl;
    }
  }
}

int main() {
  TransactionQueue queue;
  FinancialAPI* api = new RealFinancialAPI(); // Initialize with a real API implementation

  // Start multiple transaction processor threads
  std::vector<std::thread> threads;
  for (int i = 0; i < 4; ++i) {
    threads.push_back(std::thread(processTransactions, std::ref(queue), api));
  }

  // Simulate incoming transactions
  for (int i = 0; i < 100; ++i) {
    Transaction transaction{i, "transfer", 100.00, "USD"};
    queue.enqueue(transaction);
  }

  // Join threads to ensure completion
  for (auto& thread : threads) {
    thread.join();
  }

  delete api; 

  return 0;
}
```



