  void handleUpdate(const DroneConfigUpdate& update) {
    std::lock_guard<std::mutex> lock(mtx_);
    droneConfigs_[update.droneId] = update.config;
    cv_.notify_all(); 
  }

  // Method to fetch latest configuration for a drone
  std::string getDroneConfig(const std::string& droneId) {
    std::lock_guard<std::mutex> lock(mtx_);
    return droneConfigs_.at(droneId);
