      cv_.wait(lock, [this]() { return !updateQueue_.empty(); }); 
      DroneConfigUpdate update = updateQueue_.front();
      updateQueue_.pop();
      lock.unlock();

      // Apply update to drone (e.g., send over network)
      handleUpdate(update);
    }
  }
};


