            executor.submit(monitor::start);
        }
    }

    // ... other methods for configuration management, error handling, logging, etc.

    class ServiceMonitor implements Runnable {
        private final String serviceName;
        private final ServiceConfig config;

        public ServiceMonitor(String serviceName, ServiceConfig config) {
            this.serviceName = serviceName;
            this.config = config;
        }

        @Override
        public void run() {
            while (true) {
                try {
                    // Perform service health check based on config
                    if (checkServiceHealth()) {
                        LOGGER.info("Service {} is healthy", serviceName);
                    } else {
                        handleServiceFailure(serviceName);
                    }
                    Thread.sleep(config.getCheckInterval()); // Adjust interval as needed
                } catch (InterruptedException e) {
                    LOGGER.error("Service monitoring interrupted for service {}", serviceName, e);
