    try {
        $redisClient = new Redis(); // Connect to Redis cache
        $cacheKey = "clinic_status_$clinicId";
        $cachedStatus = $redisClient->get($cacheKey);
        if ($cachedStatus !== false) {
            // Use cached status 
            echo "Using cached status for clinic: $clinicId\n";
        } else {
            $dbConnection = new PDO(sprintf("mysql:host=%s;dbname=%s", getenv('DB_HOST'), getenv('DB_NAME')), getenv('DB_USER'), getenv('DB_PASSWORD'));
            $stmt = $dbConnection->prepare("UPDATE clinics SET status = :newStatus WHERE id = :clinicId");
            $stmt->bindParam(':newStatus', $newStatus);
            $stmt->bindParam(':clinicId', $clinicId);
            if ($stmt->execute()) {
                // Update cache in Redis
                $redisClient->set($cacheKey, $newStatus, 60); // Cache for 60 seconds
            } else {
                // Handle database error
                throw new Exception("Database update failed.");
            }
        }

    } catch (Exception $e) {
        // Log the error
        echo "Error updating clinic status: " . $e->getMessage() . "\n";
        return false; 
    }

    // 4. Notification
