        // Log Data Generation (Simulated)
        for (int i = 0; i < 10000; i++) {
            String logMessage = "Log Message: " + i;
            producer.send(new ProducerRecord<>("logs", logMessage)); // Send to "logs" topic
            Thread.sleep(1); // Simulate log generation rate
        }

        // Flush and close producer
        producer.close();
    }
}
