class MediaProcessor {
public:
    MediaProcessor() : processingQueue(), processingThread(std::bind(&MediaProcessor::processFiles, this)) {
        processingThread.detach();
    }

    void enqueueFile(const std::string& filePath) {
        std::unique_lock<std::mutex> lock(processingMutex);
        processingQueue.push(filePath);
        conditionVariable.notify_one();
    }

private:
    void processFiles() {
        while (true) {
            std::unique_lock<std::mutex> lock(processingMutex);
            conditionVariable.wait(lock, [this] { return !processingQueue.empty(); });
            auto filePath = processingQueue.front();
            processingQueue.pop();
            lock.unlock();

            // Transcode and process the file (omitted for brevity)
            std::cout << "Processing: " << filePath << std::endl; 
        }
    }

    std::queue<std::string> processingQueue;
    std::mutex processingMutex;
    std::condition_variable conditionVariable;
    std::thread processingThread;
};


int main() {
    MediaProcessor processor;
    processor.enqueueFile("video1.mp4");
    processor.enqueueFile("audio1.wav");

    return 0;
}



```




**Explanation:**


This code demonstrates a basic framework for your media processing application. 

