public class RandomValueGenerator
{
    private readonly Dictionary<string, CachedRandom> _cachedGenerators = new();

    public int GenerateInt(int min, int max, bool inclusive = true) 
    {
        return GetCachedGenerator($"{min}_{max}_{inclusive}").GenerateInt(min, max, inclusive);
    }

    public float GenerateFloat(float min, float max, bool inclusive = true)
    {
        return GetCachedGenerator($"{min}_{max}_{inclusive}").GenerateFloat(min, max, inclusive);
    }

    public void SetSeed(int seed) 
    {
        foreach (var generator in _cachedGenerators.Values)
        {
            generator.SetSeed(seed);
        }
    }

    private CachedRandom GetCachedGenerator(string key)
    {
        if (!_cachedGenerators.TryGetValue(key, out var generator))
        {
            generator = new CachedRandom();
            _cachedGenerators[key] = generator;
        }
        return generator;
    }
}

