class NFAPICRCIndicationManager {
 public:
  NFAPICRCIndicationManager(int max_indications = 1024) : max_indications_(max_indications) {}

  void AddIndication(const NFAPI_CRC_INDICATION_PDU_T& indication) {
    {
      std::lock_guard<std::mutex> lock(mutex_);
      if (indications_.size() < max_indications_) {
        indications_.push(indication);
      } else {
        // Handle overflow - log, discard, etc.
      }
    }
    cv_.notify_one(); // Notify consumers
  }

  NFAPI_CRC_INDICATION_PDU_T GetNextIndication() {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return !indications_.empty(); }); 
    NFAPI_CRC_INDICATION_PDU_T indication = indications_.front();
    indications_.pop();
    return indication;
  }

 private:
  std::queue<NFAPI_CRC_INDICATION_PDU_T> indications_;
  int max_indications_;
  std::mutex mutex_;
  std::condition_variable cv_;
};


``` 



