    public int GenerateRandomInt(int min, int max, string keyPrefix)
    {
        var cacheKey = $"{_cachePrefix}_{keyPrefix}_{min}_{max}";
        if (_redisCache.Exists(cacheKey))
        {
            return _redisCache.StringGet(cacheKey).ToString().GetHashCode();
        }

        var random = new Random(); 
