using System.Reflection;
using Newtonsoft.Json;

public class JsonObjectParser
{
    private readonly Dictionary<string, Func<dynamic, object>> _factoryMap = new Dictionary<string, Func<dynamic, object>>();

    public T ParseObject<T>(dynamic json) where T : new()
    {
        var typeName = typeof(T).Name;
        if (!_factoryMap.ContainsKey(typeName))
        {
            // Lazy loading of factory functions
            _factoryMap[typeName] = (json) =>
            {
                return JsonConvert.DeserializeObject<T>(json); 
            };
        }

        return _factoryMap[typeName](json); 
    }
}   


