class Logger {
 public:
  Logger(const std::string& configPath) : 
    retryAttempts_(5),
    backoffDelay_(std::chrono::milliseconds(100)),
    localStoragePath_("") {
    // Load configuration from configPath and environment variables
  }

  void LogError(const std::string& message) {
    auto loggerThread = std::thread([this, message]() {
      for (int attempt = 0; attempt < retryAttempts_; ++attempt) {
        if (SendToLoggingService(message)) {
          return; // Successfully logged
        } else {
          // Adjust backoff delay based on service health and network conditions
          std::this_thread::sleep_for(backoffDelay_);
          backoffDelay_ *= 2; // Exponential backoff
        }
      }
      // Fallback to local storage
      HandleLocalStorageWrite(message);
    });

    loggerThread.detach(); 
  }

 private:
