import java.util.List;
import java.util.concurrent.CompletableFuture;

public class PokemonWeaknessService {

    private final PokemonWeaknessApi api;

    public PokemonWeaknessService(PokemonWeaknessApi api) {
        this.api = api;
    }

    public List<PokemonWeaknessReport> generateReports(List<Pokemon> pokemons) {
        if (pokemons.isEmpty()) {
            return List.of(); 
        }
        return pokemons.stream()
                .map(pokemon -> CompletableFuture.supplyAsync(() -> {
                    try {
                        WeaknessData weaknessData = api.getWeaknessData(pokemon.getType());
                        return new PokemonWeaknessReport(pokemon.getName(), weaknessData.getWeaknesses());
                    } catch (Exception e) {
                        return new PokemonWeaknessReport(pokemon.getName(), "Weakness data unavailable"); 
                    }
                }))
                .map(CompletableFuture::join)
                .toList();
    }

}


```




