# CacheManager.py

import os
import sys
from abc import ABC, abstractmethod
from threading import Lock
from typing import Callable, Dict, Tuple

class Backend(ABC):
    @abstractmethod
    def get(self, key: str) -> any:
        pass
    @abstractmethod
    def set(self, key: str, value: any, expiry: int = 0) -> None:
        pass
    @abstractmethod
    def delete(self, key: str) -> None:
        pass

class InMemoryBackend(Backend):
    _cache: Dict[str, any] = {}
    _lock: Lock = Lock()

    def get(self, key: str) -> any:
        with self._lock:
            return self._cache.get(key)

    def set(self, key: str, value: any, expiry: int = 0) -> None:
        with self._lock:
            self._cache[key] = (value, expiry)

    def delete(self, key: str) -> None:
        with self._lock:
            del self._cache[key]

class DiskBackend(Backend):  # Placeholder - Requires file system interaction
    pass

class RemoteBackend(Backend):  # Placeholder - Requires network communication
    pass


class CacheManager:
    def __init__(self, backends: Dict[str, Callable[[], Backend]] = None):
        self._backends: Dict[str, Backend] = {}
        if not backends:
            backends = {
                'in_memory': lambda: InMemoryBackend(),
                # Add other backend configurations here
            }
        for name, factory in backends.items():
            backend = factory()
            self._backends[name] = backend

    def get(self, key: str, backend_name: str = 'in_memory') -> any:
        return self._backends[backend_name].get(key)

    def set(self, key: str, value: any, expiry: int = 0, backend_name: str = 'in_memory'):
        self._backends[backend_name].set(key, value, expiry)

    # Add other methods (delete, evict, etc.) based on your caching strategy



if __name__ == "__main__":
    cache_manager = CacheManager()

    # Example usage:
    cache_manager.set('my_key', 'my_value')
    value = cache_manager.get('my_key') 
    print(value) 


```



