import java.util.*;

public class DisjointPairs {

    private int[] parent;
    private int[] rank;

    public DisjointPairs(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public int countDisjointPairs(int[] arr) {
        long startTime = System.currentTimeMillis();
        int disjointCount = 0;
        for (int i = 0; i < arr.length; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (find(arr[i]) != find(arr[j])) {
                    disjointCount++;
                    System.out.println("Disjoint pair: (" + arr[i] + ", " + arr[j] + ")");
                }
            }
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Time taken for disjoint pair check: " + (endTime - startTime) + " milliseconds");
        return disjointCount;
    }

}



