import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    public static void main(String[] args) throws IOException, InterruptedException {
        String command = "ls -l"; // Replace with your desired command
        String fileName = "myFile.txt"; // Replace with the target file name

        // Delete existing file before execution
        try {
            Files.deleteIfExists(Paths.get(fileName));
            System.out.println("Existing file deleted: " + fileName);
        } catch (Exception e) {
            System.err.println("Failed to delete file: " + e.getMessage());
        }

        // Execute the command and capture output/error streams
        ProcessBuilder processBuilder = new ProcessBuilder(command.split("\\s+"));
        Process process = processBuilder.start();

        BufferedReader stdoutReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stderrReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        String line;
        while ((line = stdoutReader.readLine()) != null) {
            System.out.println("Standard Output: " + line);
        }

        while ((line = stderrReader.readLine()) != null) {
            System.err.println("Standard Error: " + line);
        }

        // Wait for the process to complete and check exit code
        int exitCode = process.waitFor(1, TimeUnit.MINUTES);
        if (exitCode == 0) {
            System.out.println("Command executed successfully with exit code: " + exitCode);
        } else {
            System.err.println("Command failed with exit code: " + exitCode);
        }

        // Close readers and process
        stdoutReader.close();
        stderrReader.close();
        process.destroy();
    }
}
```



