// Configuration parsing
function loadConfigurationFromDirectory($directory) {
  $configObjects = [];
  foreach (scandir($directory) as $file) {
    if (in_array(pathinfo($file, PATHINFO_EXTENSION), ['json', 'yaml'])) {
      $filePath = "$directory/$file";
      switch (pathinfo($file, PATHINFO_EXTENSION)) {
        case 'json':
          $configObjects[] = json_decode(file_get_contents($filePath), true);
          break;
        case 'yaml':
          $configObjects[] = yaml_parse_file($filePath);
          break;
      }
    } 
  }
  return $configObjects;
}

