typedef struct {
    char *filename;
    int digits;
} FileData;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FileData buffer[1024]; // Example buffer size
static int head = 0;
static int tail = 0;


void processFilename(FileData *data) {
    // Apply configuration rules to modify the filename extension
}

void* consumerThread(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        while (head == tail) {
            pthread_cond_wait(&condition, &mutex); 
        }
        FileData data = buffer[tail];
        tail = (tail + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&mutex);

        processFilename(&data); // Process the filename
    }
}

void enqueueFilename(const char *filename, int digits) {
    FileData data;
    strcpy(data.filename, filename);
    data.digits = digits;

    pthread_mutex_lock(&mutex);
    buffer[head] = data;
    head = (head + 1) % BUFFER_SIZE;
    pthread_cond_signal(&condition); // Signal the consumer thread
    pthread_mutex_unlock(&mutex);
}


int main() {
    // Initialize configuration service, memory pool, and threads

    pthread_t consumerThreadID;
    pthread_create(&consumerThreadID, NULL, consumerThread, NULL);

    // Receive filenames from input source (e.g., file stream, network socket) 
    while (1) {
        char filename[256];
        int digits = 0; // ... Read filename and digit count from input
        enqueueFilename(filename, digits);
    }

    return 0;
}


