class Transaction {
public:
  Transaction(int id, double amount, std::string currency) :
    id(id), amount(amount), currency(currency) {}

  int id;
  double amount;
  std::string currency;
};

class Logger {
public:
  void log(const std::string& message, int level) {
    // Implement logging logic here. 
    // Consider different output destinations and log levels.
  }
};

class TransactionProcessor {
private:
  std::queue<Transaction> transactionQueue;
  std::mutex queueMutex;
  std::condition_variable queueCV;
  bool running = true;
public:
  void processTransactions() {
    while (running) {
      std::unique_lock<std::mutex> lock(queueMutex);
      queueCV.wait(lock, [this]{ return !transactionQueue.empty(); });

      Transaction transaction = transactionQueue.front();
      transactionQueue.pop();
      lock.unlock();

      // Process the transaction here.
    }
  }

  void addTransaction(const Transaction& transaction) {
    std::lock_guard<std::mutex> lock(queueMutex);
    transactionQueue.push(transaction);
    queueCV.notify_one();
  }
};

int main() {
  Logger logger;
  TransactionProcessor processor;

  // Start processing transactions in a separate thread.
  std::thread processingThread(&TransactionProcessor::processTransactions, &processor);


  // Simulate adding transactions.
  for (int i = 0; i < 100; ++i) {
    Transaction transaction(i, 100.0 + i, "USD");
    processor.addTransaction(transaction);
  }

  processingThread.join();


  return 0;
}
```



