using System;
using System.Net;
using System.Threading.Tasks;

public async Task<HttpResponseMessage> UpdatePageElement(string pageSectionId, string elementId, string htmlContent)
{
    try
    {
        // Validate inputs
        if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId))
        {
            return Request.CreateResponse(HttpStatusCode.BadRequest, "Invalid request parameters.");
        }

        var updateResult = await _pageElementService.UpdateElementAsync(pageSectionId, elementId, htmlContent);

        if (updateResult.Success)
        {
            // Return refresh status based on updateResult
            return Request.CreateResponse(HttpStatusCode.OK, new { RefreshRequired = updateResult.RefreshRequired });
        }
        else
        {
            // Handle update failure, log error and return appropriate response
            _logger.LogError(updateResult.ErrorMessage); 
            return Request.CreateResponse(HttpStatusCode.InternalServerError, "Failed to update element.");
        }
    }
    catch (Exception ex)
    {
        // Handle unexpected errors, log exception and return appropriate response
        _logger.LogError(ex, "Unexpected error occurred during page element update."); 
        return Request.CreateResponse(HttpStatusCode.InternalServerError, "An unexpected error occurred.");
    }
}

```



