#include <mutex>
#include <condition_variable>
#include <atomic>
#include <queue>
#include <thread>
#include <iostream>
#include <chrono>

class Semaphore {
 public:
  Semaphore(int initial_value) : count_(initial_value), cv_() {}

  void wait() {
    std::unique_lock<std::mutex> lock(mutex_);
    while (count_ == 0) {
      cv_.wait(lock);
    }
    --count_;
  }

  void signal() {
    std::lock_guard<std::mutex> lock(mutex_);
    ++count_;
    cv_.notify_one();
  }

 private:
  int count_;
  std::mutex mutex_;
  std::condition_variable cv_;
};

```



