    return rng_.operator()();
  }

  int generateInt(int min, int max) {
    std::lock_guard<std::mutex> lock(lock_);
    return std::uniform_int_distribution<>(min, max)(rng_);
  }

private:
  std::mt19937 rng_;
  std::mutex lock_;
};

int main() {
  SecureRNG rng;

  // ... (Usage of the SecureRNG service) 

  return 0;
}
