public static MoSTState loadSerializedState(String filePath) throws IOException {
  try (FileInputStream fileInputStream = new FileInputStream(filePath)) {
    ObjectInputStream objectInputStream = new ObjectInputStream(fileInputStream);
    MoSTState state = (MoSTState) objectInputStream.readObject();
    return state;
  } catch (ClassNotFoundException e) {
    // Handle serialization format mismatch
    System.err.println("Serialization format mismatch: " + e.getMessage());
    throw new RuntimeException("Invalid serialized state file.", e);
  } catch (IOException e) {
    // Handle network latency, file access permissions, etc.
    if (TransientFailureHandler.isTransient(e)) {
      System.err.println("Transient failure loading state: " + e.getMessage());
      return null; // Retry later
    } else {
      throw new RuntimeException("Failed to load serialized state.", e);
    }
  }
}
