    validateReference(data.reference).then((isValid) => {
      if (isValid) {
        // Update dialog field in database and broadcast update via WebSocket
        socket.emit('dialogUpdated', { success: true }); 
      } else {
        socket.emit('dialogUpdated', { success: false, error: 'Invalid Bible reference' });
      }
    });
  });

  socket.on('disconnect', () => {
    console.log('User disconnected');
  });
});

// Reference validation function (handles rate limiting and outages)
async function validateReference(reference) {
  try {
    const cachedResult = redisClient.get(`bible_ref:${reference}`);
    if (cachedResult) {
      return JSON.parse(cachedResult); // Return cached result if available
    }

    // Call third-party API
    const response = await axios.get(`https://api.biblevalidation.com/${reference}`); 
    const isValid = response.data;

    // Store result in cache and return
    redisClient.set(`bible_ref:${reference}`, JSON.stringify(isValid), 'EX', 3600); // Cache for 1 hour
    return isValid;

  } catch (error) {
    console.error('Validation error:', error);
    // Handle API errors, timeouts, etc. - Implement retries or fallback mechanisms
    return false; // Return false in case of error
  }
}


