import re

def extract_old_testament_books(text):
    pattern = r"\b(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b"
    matches = re.findall(pattern, text, re.IGNORECASE)
    book_counts = {}
    for match in matches:
        if match in book_counts:
            book_counts[match] += 1
        else:
            book_counts[match] = 1
    return book_counts 
