class DataProcessingPipeline {
private:
    std::queue<std::string> dataQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    SpatialQueryEngine* spatialQueryEngine;
    DataStorage* dataStorage;

public:
    DataProcessingPipeline(SpatialQueryEngine* spatialQueryEngine, DataStorage* dataStorage) : 
        spatialQueryEngine(spatialQueryEngine), dataStorage(dataStorage) {}

    void ingestData(const std::string& data) {
        std::lock_guard<std::mutex> lock(queueMutex);
        dataQueue.push(data);
        queueCondVar.notify_one();
    }

    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCondVar.wait(lock, [this] { return !dataQueue.empty(); });

            std::string data = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            // Process geospatial data 
            spatialQueryEngine->executeQuery(data); 
            dataStorage->insert(data); 
        }
    }
};



