fn reduce<F>(arr: &[i32], mut callback: F) -> i32 
where
    F: FnMut(i32, i32) -> i32
{
    let (mut acc, iter) = (arr[0], arr.iter().skip(1));

    for val in iter {
        acc = callback(acc, *val); 
    }

    acc
}
