class StorageManager:
    def __init__(self):
        self.providers = {
            'aws': AWSProvider(), 
            'azure': AzureProvider(),
            # ... Other providers
        }
        self.selected_provider = None

    def select_provider(self, criteria):
        # ... Logic to choose provider based on cost, performance, region 

    def perform_operation(self, operation_type, filename, data=None):
        if not self.selected_provider:
            self.select_provider(criteria)  

        if operation_type == 'upload':
            self.selected_provider.upload_file(filename, data)
        elif operation_type == 'download':
            self.selected_provider.download_file(filename)
        elif operation_type == 'delete':
            self.selected_provider.delete_file(filename)

# Example Usage:
