    std::cout << "Processing data: " << data << std::endl; 
    // Implement actual processing logic here
  }
};

class DataStreamHandler {
public:
  void ingestData(const std::string& data) {
    {
      std::lock_guard<std::mutex> lock(_mutex); // Acquire mutex for thread safety
      _dataQueue.push(data); 
    }
    // Notify processing threads about new data
    _processingCondition.notify_one(); 
  }

private:
  std::queue<std::string> _dataQueue;
  std::mutex _mutex;
  std::condition_variable _processingCondition;
};

int main() {
  GeoDataProcessor processor;
  DataStreamHandler handler;

  // Simulated data stream ingestion 
  for (int i = 0; i < 10; ++i) {
    handler.ingestData("Sensor Data: " + std::to_string(i));
  }

  std::thread processingThread([&processor, &handler]() {
    while (true) {
      std::unique_lock<std::mutex> lock(handler._mutex); // Acquire mutex
      handler._processingCondition.wait(lock, [&handler]() { return !handler._dataQueue.empty(); }); 

      if (!handler._dataQueue.empty()) {
        auto data = handler._dataQueue.front();
        handler._dataQueue.pop();

        processor.processData(data); 
      }
    }
  });

  // Keep main thread alive to prevent processingThread from exiting immediately
  processingThread.join(); 


  return 0;
}
``` 




