class LogEntry {
public:
    std::string source;
    std::string format;
    std::string content;
};

class LogProcessor {
private:
    std::queue<LogEntry> logQueue;
    std::mutex queueMutex;

public:
    void ingestLog(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(queueMutex);
        logQueue.push(entry);
    }

    void processLogs() {
        while (true) {
            LogEntry entry;
            {
                std::lock_guard<std::mutex> lock(queueMutex);
                if (!logQueue.empty()) {
                    entry = logQueue.front();
                    logQueue.pop();
                } 
            }
            // Process the log entry here
            std::cout << "Processing log: " << entry.content << std::endl;
        }
    }
};

int main() {
    LogProcessor processor;
    std::thread processingThread(&LogProcessor::processLogs, &processor);

    // Simulate ingesting logs from various sources
    processor.ingestLog({"source1", "JSON", "{'key': 'value'}"});
    processor.ingestLog({"source2", "plain text", "This is a log message"});

    processingThread.join(); 
    return 0;
}

```



**Explanation:**


* **`LogEntry` Class:** Represents a single log entry with fields for source, format, and content.
* **`LogProcessor` Class:**
