pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void rename_file(const char *old_filename, const char *new_filename) {
    pthread_mutex_lock(&mutex); // Ensure thread safety
    FILE *input = fopen(old_filename, "r"); 
    if (input == NULL) {
        fprintf(stderr, "Error opening file: %s\n", old_filename);
        return; 
    }
    FILE *output = fopen(new_filename, "w"); // Create new file
    if (output == NULL) {
        fprintf(stderr, "Error creating file: %s\n", new_filename);
        fclose(input);
        return;
    }

    char buffer[1024]; 
    while (fgets(buffer, sizeof(buffer), input) != NULL) {
        fputs(buffer, output); // Copy content from old to new file
    }
    fclose(input);
    fclose(output);  

    // Log the modification event
    LogEntry entry = { .old_filename = old_filename, .new_filename = new_filename }; 
    log_modification(&entry); 
    pthread_mutex_unlock(&mutex); // Release lock
}



int main() {
  // Example usage: 
  rename_file("input.txt", "output.txt");

  return 0;
} 
