#include <atomic>
#include <mutex>
#include <thread>
#include <queue>
#include <condition_variable>

class Semaphore {
public:
    Semaphore(int initialValue) : value_(initialValue), mutex_() {}

    void acquire() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (value_ == 0) {
            cv_.wait(lock); // Wait until a semaphore is available
        }
        --value_;
    }

    void release() {
        std::unique_lock<std::mutex> lock(mutex_);
        ++value_;
        cv_.notify_one(); // Notify a waiting thread
    }

private:
    int value_;
    std::mutex mutex_;
    std::condition_variable cv_;
};
```



