import java.util.*;
import java.util.concurrent.*;

public class MessageDeduplicationService {

    private final Map<String, Set<String>> processedMessages = new ConcurrentHashMap<>(); 
    private final ThreadPoolExecutor executor;
    private final DistributedConfigStore configStore;

    public MessageDeduplicationService(DistributedConfigStore configStore) {
        this.configStore = configStore;
        int corePoolSize = Integer.parseInt(configStore.getValue("corePoolSize"));
        int maximumPoolSize = Integer.parseInt(configStore.getValue("maximumPoolSize"));
        long keepAliveTime = Long.parseLong(configStore.getValue("keepAliveTime"));
        TimeUnit unit = TimeUnit.valueOf(configStore.getValue("unit"));
        executor = new ThreadPoolExecutor(corePoolSize, 
                                        maximumPoolSize, 
                                        keepAliveTime, 
                                        unit,
                                        new LinkedBlockingQueue<>(), 
                                        Executors.defaultThreadFactory());
    }

    public void processMessage(String message) {
        if (processedMessages.computeIfAbsent(message, k -> new HashSet<>()).add(message)) {
            executor.execute(() -> {
                // Process the message asynchronously
                System.out.println("Processing message: " + message); 
            });
        }
    }

    public void shutdown() {
        executor.shutdown();
    }

}



