import java.util.*;
import java.util.concurrent.TimeUnit;

public class DocumentProcessor {

    private final UnionFind uf = new UnionFind();

    // ... other document processing logic ...

    public void checkDisjointnessAsync(int[] array) {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        executor.submit(() -> {
            long startTime = System.currentTimeMillis();
            for (int i = 0; i < array.length; i++) {
                for (int j = i + 1; j < array.length; j++) {
                    if (!uf.find(array[i]) == uf.find(array[j])) {
                        System.out.println("Disjoint pair: " + array[i] + ", " + array[j]);
                    }
                }
            }
            long endTime = System.currentTimeMillis();
            long timeTaken = endTime - startTime;
            System.out.println("Total time taken: " + timeTaken + " milliseconds");
        });
    }

    // ... other microservice logic ...
}


class UnionFind {
    private int[] parent;
    private int[] rank;
    private int numSets;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];
        numSets = n;
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
            numSets--;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }
}
