    true, // Exclusive consumer
    false, // No local queue processing
    false, // no passive flag 
    function($message) {
        // Process command asynchronously using the middleware function
        processCommand(json_decode($message->body, true)); 
        $channel->basic_ack($message->delivery_info['delivery_tag']);  
    }
);

