function refreshDialogFields(resourceId, url) {
  // Fetch data from the URL
  fetch(url)
    .then(response => response.json())
    .then(data => {
      // Iterate through dialog fields
      for (const field of document.querySelectorAll('.dialog-field')) {
        const fieldName = field.getAttribute('name');

        if (fieldName in data) {
          // Set the field value
          field.value = data[fieldName]; 
          // Send message to parent window for successful update
          window.parent.postMessage({ status: 'success', field: fieldName, value: data[fieldName] }, '*'); 
        }
      }
    })
    .catch(error => {
      console.error('Error refreshing fields:', error);
      // Handle errors
    });
}



