public class RegistrationManager : IDisposable
{
    private readonly Dictionary<Type, ServiceInstance> _services = new Dictionary<Type, ServiceInstance>();
    private readonly ILoggerFactory _loggerFactory;
    private readonly IServiceProvider _serviceProvider;

    public RegistrationManager(ILoggerFactory loggerFactory, IServiceProvider serviceProvider)
    {
        _loggerFactory = loggerFactory ?? throw new ArgumentNullException(nameof(loggerFactory));
        _serviceProvider = serviceProvider ?? throw new ArgumentNullException(nameof(serviceProvider));
    }

    public void RegisterService<T>(string configurationPath) where T : Service
    {
        try
        {
            var serviceInfo = LoadServiceInfo(configurationPath);
            if (_services.ContainsKey(typeof(T))) 
            {
                _loggerFactory.CreateLogger<RegistrationManager>().LogWarning("Service type '{0}' already registered.", typeof(T));
                return;
            }

            var instance = CreateAndInitializeInstance<T>(serviceInfo);
            _services.Add(typeof(T), instance);
        }
        catch (Exception ex)
        {
            _loggerFactory.CreateLogger<RegistrationManager>().LogError("Failed to register service '{0}'.", typeof(T), ex);
        }
    }

