        public async Task<T> LoadAndProcessAsync<T>(int version)
        {
            lock (_lock)
            {
                if (_cachedData != null && _cachedData.Length > 0 && CheckVersion(_cachedData, version))
                {
                    return DeserializeDataFromCache<T>();
