    public void ModifyConfigFile(string inputFile, Dictionary<string, string> placeholders)
    {
        // Create a list of sed commands for each placeholder replacement. 
        List<string> sedCommands = placeholders
            .Select(p => $"s/\{p.Key\}/\{p.Value\}/")
            .ToList();

        // Construct the Python command using subprocess module.
        string pythonCommand = $"/usr/bin/python {_pythonScriptPath} '{inputFile}' {sedCommands.JsonSerialize()}";

        try
        {
            // Execute the Python command and capture the output.
            Process process = new Process();
            process.StartInfo.FileName = "/bin/bash";
            process.StartInfo.Arguments = pythonCommand;
            process.StartInfo.UseShellExecute = false; 
            process.StartInfo.RedirectStandardOutput = true;
            process.Start();

            // ... (Handle output and potential errors) ...

        }
        catch (Exception ex)
        {
            throw new Exception("Error modifying Kickstart configuration file:", ex);
        }
    }
}



