```python
import sys
import json
import subprocess

def modify_config(input_file, sed_commands):
    with open(input_file, 'r') as f:
        content = f.read()
    for command in sed_commands:
        try:
            subprocess.run(['sed', '-i', command], input=content)  
        except subprocess.CalledProcessError as e:
            raise Exception(f"Error executing SED command: {e}") 

if __name__ == "__main__":
    input_file = sys.argv[1]
    # Load sed commands from JSON data passed as arguments
    sed_commands = json.loads(sys.argv[2])  
    modify_config(input_file, sed_commands) 

```



