// Refactored Java code to delete a file before executing a command
public class SecureCommandExecutor {

    private static final Logger logger = LoggerFactory.getLogger(SecureCommandExecutor.class);

    public void executeCommand(String filePath, String command) throws IOException, InterruptedException {
        File fileToDelete = new File(filePath);
        if (fileToDelete.exists()) {
            boolean success = fileToDelete.delete();
            logger.info("File {} deleted: {}", filePath, success);
        }

        Process process = Runtime.getRuntime().exec(command);
        process.waitFor();
        int exitCode = process.exitValue();
        logger.info("Command execution completed with exit code: {}", exitCode);
    }
}


