['```javascript
function traverseDom(node, selector, callback) {
  if (callback(node)) {
    return [node];
  }

  const foundElements = [];

  for (let i = 0; i < node.childNodes.length; i++) {
    const childNodes = traverseDom(node.childNodes[i], selector, callback);
    foundElements.push(...childNodes);
  }

  return foundElements;
}
```']

