std::atomic<int> lastAttack = 0;
std::mutex attackMutex;
std::random_device rd;  
std::mt19937 gen(rd()); 
std::uniform_int_distribution<> distrib(1, 2);

void selectAttack() {
    // Acquire lock for thread safety.
    std::lock_guard<std::mutex> lock(attackMutex);

    // Generate a random attack choice.
    int attack = distrib(gen);

    // Update the last attack selection.
    lastAttack = attack; 

    // Print the selected attack number to the console.
    std::cout << "Selected attack: " << attack << std::endl;

    // Enforce the cooldown period.
    std::this_thread::sleep_for(std::chrono::seconds(9));
}
