#include <iostream>
#include <random>
#include <limits>

class DynamicValueGenerator {
 private:
  std::default_random_engine generator_;
  std::uniform_real_distribution<float> float_distrib_;
  std::uniform_int_distribution<int> int_distrib_;
  float min_value_;
  float max_value_;

 public:
  DynamicValueGenerator(float min, float max)
      : generator_(std::random_device{}()),
        float_distrib_(min, max),
        int_distrib_(static_cast<int>(min), static_cast<int>(max)),
        min_value_(min),
        max_value_(max) {}

  float generateFloat() { return float_distrib_(generator_); }
  int generateInt() { return int_distrib_(generator_); }

  std::string toString() const {
    return "Range: [" + std::to_string(min_value_) + ", " + std::to_string(max_value_) + "]";
  }
};

int main() {
  DynamicValueGenerator generator(0.0f, 10.0f);
  std::cout << generator.toString() << std::endl;
  std::cout << "Random float: " << generator.generateFloat() << std::endl;
  std::cout << "Random int: " << generator.generateInt() << std::endl;

  return 0;
}
