#include <iostream>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>

class SensorData {
public:
  double temperature;
  float humidity;
  int pressure;
};

class SensorInterface {
public:
  virtual ~SensorInterface() {}
  virtual std::shared_ptr<SensorData> readData() = 0;
};

class TemperatureSensor : public SensorInterface {
public:
  std::shared_ptr<SensorData> readData() override {
    // Simulate reading temperature data
    auto data = std::make_shared<SensorData>();
    data->temperature = 25.5;
    return data;
  }
};

class DataProcessor {
private:
  std::queue<std::shared_ptr<SensorData>> dataQueue;
  std::mutex queueMutex;
  std::condition_variable cv;

public:
  void processData() {
    while (true) {
      std::unique_lock<std::mutex> lock(queueMutex);
      cv.wait(lock, [this]{ return !dataQueue.empty(); });
      auto data = dataQueue.front();
      dataQueue.pop();
      lock.unlock();

      // Process sensor data here
      std::cout << "Temperature: " << data->temperature << std::endl;
    }
  }

  void enqueueData(std::shared_ptr<SensorData> data) {
    std::lock_guard<std::mutex> lock(queueMutex);
    dataQueue.push(data);
    cv.notify_one();
  }
};

int main() {
  // Initialize sensor and processor
  auto tempSensor = std::make_shared<TemperatureSensor>();
  DataProcessor dataProcessor;

  // Start data processing thread
  std::thread processingThread(&DataProcessor::processData, &dataProcessor);

  // Read data from sensor and enqueue
  while (true) {
    auto data = tempSensor->readData();
    dataProcessor.enqueueData(data);
  }

  return 0;
}
```



