#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <thread>
#include <chrono>
#include <iostream>
// ... Additional includes for logging, database, observability platform

class Semaphore {
 public:
  Semaphore(int initial_value) : value_(initial_value), cv_() {}

  bool acquire() {
    std::unique_lock<std::mutex> lock(mtx_);
    while (value_ == 0) {
      cv_.wait(lock);
    }
    --value_;
    return true;
  }

  void release() {
    std::lock_guard<std::mutex> lock(mtx_);
    ++value_;
    cv_.notify_one();
  }

 private:
  int value_;
  std::mutex mtx_;
  std::condition_variable cv_;
};

// ... Implementations for dynamic initialization, graceful deletion, logging, etc. 
