public class ApiGateway {

    private AuthenticationManager authenticationManager;
    private RateLimiter rateLimiter;
    private RequestRouter router;
    private ServiceDiscovery serviceDiscovery;

    // Constructor and initialization logic

    public void handleRequest(HttpServletRequest request) {
        AuthenticationResult authResult = authenticationManager.authenticate(request);
        if (!authResult.isAuthenticated()) {
            return unauthorizedResponse(request); 
        }

        RateLimitResult limitResult = rateLimiter.checkLimits(request, authResult.getUser());
        if (limitResult.isExceedingLimits()) {
            return throttledResponse(request);
        }

        ServiceInstance instance = serviceDiscovery.getInstanceForRoute(request.getPath());
        if (instance == null) {
            return notFoundResponse(request);
        }

        String response = router.routeRequest(request, instance);
        return successfulResponse(request, response); 
    }

