class PacketAssembler {
public:
    PacketAssembler(size_t initialCapacity = 1024) : bufferSize(initialCapacity) {
        packets.reserve(bufferSize);
    }

    void addPacket(const NFAPI_L2_PDU_T& packet) {
        std::lock_guard<std::mutex> lock(mutex);
        packets.push_back(packet);
        cv.notify_one(); 
    }

    std::vector<NFAPI_L2_PDU_T> assemblePackets() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this]{ return !packets.empty(); });
        std::vector<NFAPI_L2_PDU_T> assembledPackets = std::move(packets); 
        packets.clear(); 
        return assembledPackets;
    }

private:
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<NFAPI_L2_PDU_T> packets;
    size_t bufferSize;
};
