import java.util.*;

public class DisjointPairs {

    private int[] parent;
    private int[] rank;

    public DisjointPairs(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int i) {
        if (parent[i] != i) {
            parent[i] = find(parent[i]);
        }
        return parent[i];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public long countDisjointPairs(int[] arr) {
        long startTime = System.nanoTime();
        int n = arr.length;
        DisjointPairs uf = new DisjointPairs(n);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (uf.find(arr[i]) != uf.find(arr[j])) {
                    // Pair is disjoint
                    uf.union(arr[i], arr[j]);
                    System.out.println("Disjoint pair found: " + arr[i] + ", " + arr[j]);
                }
            }
        }
        long endTime = System.nanoTime();
        long elapsedTime = endTime - startTime;
        System.out.println("Time taken: " + elapsedTime / 1000000 + " ms");
        return (endTime - startTime) / 1000000;
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5, 6, 7};
        DisjointPairs disjointPairs = new DisjointPairs(arr.length);
        long timeTaken = disjointPairs.countDisjointPairs(arr);
        System.out.println("Total time taken: " + timeTaken + " ms");
    }
}

