# Python API Client

import requests
from time import sleep

class APIClient:
    def __init__(self, base_url):
        self.base_url = base_url
        self.retries = 0

    def make_request(self, method, endpoint, data=None):
        while self.retries < 3:
            try:
                response = requests.request(method, f'{self.base_url}{endpoint}', json=data)
                response.raise_for_status()  # Raise exception for bad status codes
                return response.json()
            except requests.exceptions.RequestException as e:
                print(f'Error making request: {e}')
                self.retries += 1
                sleep(2**self.retries) # Exponential backoff

        raise Exception("Max retries exceeded")



# ... other API client methods for different endpoints ...

client = APIClient("https://api.example.com")
user_data = client.make_request("POST", "/users", {"name": "John Doe"})

