fn select_attack() {
    // Code to randomly select an attack (1 or 2)
    let attack = rand::random::<u32>() % 2 + 1;
    println!("Attack: {}", attack);

    // Cooldown implementation
    static mut last_attack_time: Option<chrono::Instant> = None;
    if let Some(last_time) = unsafe { &mut last_attack_time } {
        let now = chrono::Instant::now();
        if now - *last_time < Duration::from_secs(9) {
            return; // Cooldown not over, return
        }
    }

    // Update cooldown time
    unsafe {
        last_attack_time = Some(chrono::Instant::now()); 
    }
}
