    public void scheduleJob(String jobId, Callable callable) {
        jobQueue.put(jobId, callable); 
        // Implement a mechanism to trigger job execution (e.g., using a timer or message queue)
    }

    private void executeJobs() {
        for (Map.Entry<String, Callable> entry : jobQueue.entrySet()) {
            try {
                Callable callable = entry.getValue();
                executor.submit(callable); 
            } catch (Exception e) {
                // Implement robust error handling and retry logic
            }
        }
    }

    public void start() {
        while (true) {
            executeJobs();
            try {
                Thread.sleep(60 * 1000); // Check for new jobs every minute
            } catch (InterruptedException e) {
                // Handle interruption gracefully
            }
        }
    }
}



