import java.util.*;

public class DisjointPairs {

    public static int countDisjointPairs(int[] arr) {
        Set<Integer> seen = new HashSet<>();
        int count = 0;
        for (int i = 0; i < arr.length; i++) {
            if (!seen.contains(arr[i])) {
                seen.add(arr[i]);
            } else {
                count++;
            }
        }
        return count;
    }
}
