        // Initialize RocksDB database
        options.create_if_missing = true;
        options.error_if_exists = false;
        db.reset(rocksdb::DB::Open(options, "weather_data"));
    }

    ~WeatherDataClient() {
        delete redisClient; 
        db->Close();
    }

    // Method to retrieve weather data for a given location
    std::string getWeatherData(const std::string& location) {
        // Fetch data from cache (Redis) first
        auto cachedData = redisClient->get(location);
        if (!cachedData.empty()) {
            return cachedData;
        }

        // If not in cache, fetch from API
        std::future<std::string> apiResult = std::async([location]() {
            // Call API based on routing logic and handle errors/retries
            std::string apiResponse = getWeatherFromAPI(location); 
            return apiResponse;
        });

        // Process API response, store in cache (Redis), and return
        std::string data = apiResult.get();
        redisClient->set(location, data); // Cache the data
        return data;
    }

