// DOMFilter.js
class DOMFilter {
  constructor(apiEndpoint) {
    this.apiEndpoint = apiEndpoint;
    this.selectorCache = {};
    this.domObserver = new MutationObserver(this.processUpdates.bind(this));
    this.retryCount = 0;
    this.maxRetries = 3;
  }

  async fetchSelectors() {
    try {
      const response = await fetch(this.apiEndpoint);
      if (!response.ok) {
        throw new Error(`API request failed: ${response.status}`);
      }
      return response.json();
    } catch (error) {
      console.error(`API fetch error: ${error}`);
      if (this.retryCount < this.maxRetries) {
        this.retryCount++;
        console.warn('Retrying API request...');
        return this.fetchSelectors();
      }
      throw error;
    }
  }

  processUpdates(mutationsList) {
    for (const mutation of mutationsList) {
      if (mutation.type === 'childList') {
        this.filterDOM(mutation.target);
      }
    }
  }

  registerObserver() {
    this.domObserver.observe(document.documentElement, { childList: true, subtree: true });
  }

  startFiltering() {
    this.fetchSelectors().then(selectors => {
      this.selectorCache = selectors;
      this.filterDOM();
      this.registerObserver();
    });
  }

  filterDOM(rootElement = document) {
    // ... Filter logic based on selectorCache and rootElement ...
  }

  addSelector(newSelector) {
    // ... Add new selector to selectorCache and re-filter DOM ...
  }

  removeSelector(selectorToRemove) {
    // ... Remove selector from selectorCache and re-filter DOM ...
  }
}



