  char *trimmedStr = malloc(sizeLimit + 1); // Allocate memory for trimmed string
  if (trimmedStr == NULL) {
    // Handle memory allocation failure
    return NULL;
  }

  strncpy(trimmedStr, str, sizeLimit);
  trimmedStr[sizeLimit] = '\0'; // Null-terminate the string

  // Check if string needs a trailing slash
  if (strlen(trimmedStr) < sizeLimit) {
    strcat(trimmedStr, "/"); 
  }
  return trimmedStr;
}


