public class DataTransformationPipeline {

    private Map<String, Transformer> transformers = new HashMap<>();

    public DataTransformationPipeline() {
        // Initialize transformers for different file formats and services
        transformers.put("csv", new CSVTransformer());
        transformers.put("json", new JSONTransformer());
        // Add more transformers as needed...
    }

    public String transformData(String inputFile, String targetFormat) {
        Transformer transformer = transformers.getOrDefault(inputFileExtension(inputFile), null);
        if (transformer == null) {
            throw new IllegalArgumentException("Unsupported file format: " + inputFile);
        }
        return transformer.transform(inputFile, targetFormat); 
    }

    private String inputFileExtension(String filename) {
        // Extract the file extension based on the filename
        int lastDotIndex = filename.lastIndexOf('.');
        if (lastDotIndex != -1) {
            return filename.substring(lastDotIndex + 1).toLowerCase(); 
        } else {
            return "unknown"; 
        }
    }

    // Example Transformer implementations:

    interface Transformer {
        String transform(String input, String targetFormat);
    }

    static class CSVTransformer implements Transformer {
        @Override
        public String transform(String input, String targetFormat) {
            // Implement CSV transformation logic
            return ""; 
        }
    }

    static class JSONTransformer implements Transformer {
        @Override
        public String transform(String input, String targetFormat) {
            // Implement JSON transformation logic
            return ""; 
        }
    }
}


```  



