using System.Data;
using System.Data.SqlClient;

public class SecureSqlCommandExecutor 
{
    public static IDataReader ExecuteSqlCommand(string sqlCommand, List<object> parameters, SqlConnection connection)
    {
        using (var command = new SqlCommand(sqlCommand, connection))
        {
            for (int i = 0; i < parameters.Count; i++)
            {
                command.Parameters.AddWithValue($"@param_{i + 1}", parameters[i]);
            }

            return command.ExecuteReader();
        }
    }
}
