        consumer = new KafkaConsumer<>(consumerConfig);
        processorChain = new ProcessorChain();
    }

    public void start() {
        consumer.subscribe(ORDER_TOPIC);
        consumer.poll().forEach(record -> processorChain.processOrder(record.value())); 
    }
}

