```java
public class UnionFind {
    private int[] parent;
    private int[] rank;
    private int numElements;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];
        numElements = n;
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int i) {
        if (parent[i] != i) {
            parent[i] = find(parent[i]); // Path compression
        }
        return parent[i];
    }

    public void union(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);
        if (rootI != rootJ) {
            if (rank[rootI] < rank[rootJ]) {
                parent[rootI] = rootJ;
            } else if (rank[rootI] > rank[rootJ]) {
                parent[rootJ] = rootI;
            } else {
                parent[rootJ] = rootI;
                rank[rootI]++;
            }
            numElements--; // Merge two sets into one
        }
    }

    public int getDisjointPairs() {
        return numElements;
    }

    // ... (Additional methods for disjoint set operations)

    public static void main(String[] args) {
        UnionFind uf = new UnionFind(10); // Create a union-find data structure
        // ... (Perform operations and check disjointness)
    }
}



```




