public class DynamicRandomValueGenerator
{
    private readonly Random _random = new(); 
    private int _minValue;
    private int _maxValue;
    private float _minFloatValue;
    private float _maxFloatValue;
    private IDataFeed _dataFeed; // Dependency injection for data feed

    public DynamicRandomValueGenerator(IDataFeed dataFeed)
    {
        _dataFeed = dataFeed;
        InitializeRanges(); // Initialize ranges based on external data
    }

    public void InitializeRanges()
    {
        var configData = _dataFeed.GetConfig(); 
        _minValue = configData.MinRandomInteger;
        _maxValue = configData.MaxRandomInteger;
        _minFloatValue = configData.MinRandomFloat;
        _maxFloatValue = configData.MaxRandomFloat;
    }

    public int GenerateRandomInteger()
    {
        return _random.Next(_minValue, _maxValue + 1); 
    }

    public float GenerateRandomFloat()
    {
        return (float)_random.NextDouble() * (_maxFloatValue - _minFloatValue) + _minFloatValue;
    }


    // ... Add other methods for error handling, circuit breakers, etc.
    // ... Implement unit and integration tests

}



