    int retryAttempts = 3;

public:
    void updateCollection(int targetValue, int replacementValue) {
        std::unique_lock<std::mutex> lock(mutex);
        for (auto it = values.begin(); it != values.end(); ++it) {
            if (*it == targetValue) {
                *it = replacementValue;
                break;
            } 
            // Validation and logging logic here
        }
        values.push_back(replacementValue); // Append if not found

        apiCallCount++;
        if (apiCallCount >= maxApiCallsPerPeriod) {
