  if (offsets_size <= 0 || keys_size <= 0 || records_size <= 0) {
    fprintf(stderr, "Error: Invalid input sizes.\n");
    return 1;
  }

  // Dynamically allocate memory for arrays
  long* offsets = (long*)malloc(offsets_size * sizeof(long));
  if (offsets == NULL) {
    fprintf(stderr, "Error: Memory allocation failed for 'offsets'.\n");
    return 2;
  }

  int* keys = (int*)malloc(keys_size * sizeof(int));
  if (keys == NULL) {
    fprintf(stderr, "Error: Memory allocation failed for 'keys'.\n");
    free(offsets);
    return 3;
  }

  Record* records = (Record*)malloc(records_size * sizeof(Record));
  if (records == NULL) {
    fprintf(stderr, "Error: Memory allocation failed for 'records'.\n");
    free(offsets);
    free(keys);
    return 4;
  }

