import org.apache.kafka.common.serialization.StringSerializer;

public class IoTScaleMicroservice {

    @Override
    protected void init() throws Exception {
        // Initialize configuration for Kafka producers and consumers
        var kafkaProps = new Properties();
        kafkaProps.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092"); 
        kafkaProps.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        kafkaProps.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());

        var consumerProps = new Properties();
        consumerProps.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092"); 
        consumerProps.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        consumerProps.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());

        // Create Kafka producers and consumers for different event streams
        var producer = new KafkaProducer<>(kafkaProps); 
        var consumer = new KafkaConsumer<>(consumerProps); 

        // Subscribe to IoT data stream
        consumer.subscribe(Collections.singletonList("iot-data-stream"));

        // Continuously process incoming messages
        while (true) {
            var records = consumer.poll(Duration.ofMillis(100));
            for (Record<String, String> record : records) {
                // Process IoT data and publish transformed events
                var transformedData = processIoTData(record.value());
                producer.send(new ProducerRecord<>("transformed-data-stream", transformedData));
            }
        }

    }


    private String processIoTData(String rawData) {
