public class MessageProcessorService
{
    private readonly ConcurrentQueue<byte[]> _messageQueue = new ConcurrentQueue<byte[]>();
    private readonly SemaphoreSlim _apiRequestSemaphore = new SemaphoreSlim(20); // Limit concurrent API calls
    private readonly HttpClient _httpClient = new HttpClient(); 

    public async Task StartAsync()
    {
        // Add logic to consume messages from the message queue here

        while (true)
        {
            if (_messageQueue.TryDequeue(out byte[] message))
            {
                await ProcessMessageAsync(message);
            }
        }
    }

    private async Task ProcessMessageAsync(byte[] message)
    {
        try
        {
            await _apiRequestSemaphore.WaitAsync();

            // Send the message to the REST API endpoint
            var response = await _httpClient.PostAsync("https://api.example.com/process", new ByteArrayContent(message));

            if (response.IsSuccessStatusCode)
            {
                Console.WriteLine($"Message processed successfully: {message}");
            }
            else
            {
                // Handle API errors gracefully, log the error, and potentially retry
                Console.WriteLine($"API request failed: {response.ReasonPhrase}"); 
            }
        }
        catch (Exception ex)
        {
            // Log the exception and handle it appropriately
            Console.WriteLine($"Error processing message: {ex.Message}");
        }
        finally
        {
            _apiRequestSemaphore.Release();
        }
    }
}
